<div class="page-intro"><p>统一查找客户，原设备授权和套餐账号保持独立。存在关联关系时可在套餐用户详情查看，不自动合并或改写授权。</p><div class="actions"><a class="btn" href="/admin/licenses/new">新增原设备授权</a><a class="btn ghost" href="/admin/shop-users">套餐用户管理</a></div></div>
<form class="filter-bar" method="get"><label>搜索客户<input type="search" name="q" value="<?= e($q) ?>" placeholder="邮箱、设备授权码、称呼或备注…"></label><label>客户类型<select name="scope"><?php foreach(['all'=>'全部记录','accounts'=>'套餐账号','legacy'=>'原设备客户'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $scope===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><button class="btn">查找客户</button><span class="muted"><?= number_format($total) ?> 条客户记录，不按关联关系去重</span></form>
<div class="card table-card"><div class="table-scroll"><table><thead><tr><th>客户 / 设备 ID</th><th>类型</th><th>授权状态</th><th>最近 7 天异常</th><th>最近事件</th><th>操作</th></tr></thead><tbody><?php foreach($rows as $row):$isAccount=$row['kind']==='account'; ?><tr><td><strong><?= e($row['name']) ?></strong><div class="muted"><?= e(mb_substr($row['description'],0,70)) ?></div></td><td><span class="type-label"><?= $isAccount?'套餐账号':'原设备客户' ?></span></td><td><?php if($isAccount): ?><?= count($row['effective']['platforms'] ?? []) ?> 个有效平台<?php else:$state=license_effective_status($row); ?><span class="badge <?= status_class($state) ?>"><?= status_label($state) ?></span><div class="muted"><?= e($row['expires_at']) ?></div><?php endif; ?></td><td><span class="<?= $row['diagnostics']['errors']?'text-danger':'' ?>"><?= (int)$row['diagnostics']['errors'] ?></span><small class="muted"> / <?= (int)$row['diagnostics']['events'] ?> 事件</small></td><td><?= e($row['diagnostics']['latest'] ?: '暂无上报') ?></td><td class="ops"><?php if($isAccount): ?><a class="btn ghost sm" href="/admin/shop-users/<?= (int)$row['id'] ?>">客户详情</a><a href="/admin/events?user_id=<?= (int)$row['id'] ?>">运行分析</a><?php else: ?><a class="btn ghost sm" href="/admin/licenses/<?= (int)$row['id'] ?>">授权详情</a><a href="/admin/userdata/<?= e(rawurlencode($row['identity'])) ?>">运行与日志</a><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="empty">没有匹配客户。可使用原授权码或邮箱重新搜索。</td></tr><?php endif; ?></tbody></table></div></div>
<nav class="pager" aria-label="客户分页"><span>第 <?= (int)$page ?> / <?= (int)$pages ?> 页</span><?php foreach(['上一页'=>$page-1,'下一页'=>$page+1] as $label=>$n):if($n<1||$n>$pages)continue; ?><a href="?<?= e(http_build_query(['scope'=>$scope,'q'=>$q,'page'=>$n])) ?>"><?= e($label) ?></a><?php endforeach; ?></nav>
